function validate([nodes]) {
  if (!Array.isArray(nodes) || nodes.length < 1 || nodes.length > 100000) return 'nodes needs 1 to 100000 entries.';
  const ids = new Set();
  for (const entry of nodes) {
    if (!Array.isArray(entry) || entry.length !== 2 || !entry.every(Number.isInteger)) return 'Each entry is a pair [id, parentId] of integers.';
    if (entry[0] < 0 || entry[0] > 100000) return 'Each id is between 0 and 100000.';
    if (entry[1] < -1 || entry[1] > 100000) return 'Each parentId is between -1 and 100000.';
    if (ids.has(entry[0])) return 'The ids must be distinct.';
    ids.add(entry[0]);
  }
  const children = new Map();
  let root = null;
  for (const [id, parentId] of nodes) {
    if (parentId === -1) {
      if (root !== null) return 'Exactly one entry is the root (parentId -1).';
      root = id;
      continue;
    }
    if (!ids.has(parentId)) return 'Every parentId must be the id of some entry.';
    if (!children.has(parentId)) children.set(parentId, []);
    children.get(parentId).push(id);
    if (children.get(parentId).length > 2) return 'A node has at most two children.';
  }
  if (root === null) return 'Exactly one entry is the root (parentId -1).';
  let reached = 0;
  const queue = [root];
  while (queue.length) {
    const id = queue.pop();
    reached++;
    for (const kid of children.get(id) || []) queue.push(kid);
  }
  if (reached !== nodes.length) return 'Every node must hang below the root (no cycles).';
  return null;
}

