function isPreorder(nodes) {
  // Try every left/right order of every node's children and compare the resulting preorder.
  const children = new Map();
  let root = -1;
  for (const [id, parentId] of nodes) {
    if (parentId === -1) root = id;
    else {
      if (!children.has(parentId)) children.set(parentId, []);
      children.get(parentId).push(id);
    }
  }
  const pairs = [...children.keys()].filter(id => children.get(id).length === 2);
  const given = nodes.map(entry => entry[0]).join(',');
  for (let mask = 0; mask < (1 << pairs.length); mask++) {
    const swapped = new Set(pairs.filter((_, bit) => (mask >> bit) & 1));
    const order = [];
    const visit = id => {
      order.push(id);
      const kids = [...(children.get(id) || [])];
      if (swapped.has(id)) kids.reverse();
      for (const kid of kids) visit(kid);
    };
    visit(root);
    if (order.join(',') === given) return true;
  }
  return false;
}

