function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const idLimit = size === 'large' ? 100001 : 12;
  // Distinct ids for the n nodes.
  const used = new Set();
  const ids = [];
  while (ids.length < n) {
    const id = Math.floor(rand() * Math.max(idLimit, n));
    if (!used.has(id)) { used.add(id); ids.push(id); }
  }
  // A random binary tree: node i hangs below an earlier node that still has room.
  const deep = rand() < 0.5;
  const kids = Array.from({ length: n }, () => []);
  const parent = new Array(n).fill(-1);
  for (let i = 1; i < n; i++) {
    for (;;) {
      const p = deep ? Math.max(0, i - 1 - Math.floor(rand() * 3)) : Math.floor(rand() * i);
      if (kids[p].length < 2) { kids[p].push(i); parent[i] = p; break; }
    }
  }
  // Its preorder with a random choice of left and right children.
  const order = [];
  const stack = [0];
  while (stack.length) {
    const v = stack.pop();
    order.push(v);
    const k = rand() < 0.5 ? [...kids[v]] : [...kids[v]].reverse();
    for (let j = k.length - 1; j >= 0; j--) stack.push(k[j]);
  }
  // About half the inputs are disturbed a little, which usually (not always) breaks the preorder.
  if (n > 1 && rand() < 0.5) {
    const a = Math.floor(rand() * n);
    const b = Math.floor(rand() * n);
    if (rand() < 0.5) [order[a], order[b]] = [order[b], order[a]];
    else order.splice(b, 0, order.splice(a, 1)[0]);
  }
  return [order.map(v => [ids[v], parent[v] === -1 ? -1 : ids[parent[v]]])];
}
